import { sql } from 'drizzle-orm'
import { boolean, index, integer, jsonb, pgTable, primaryKey, text, timestamp, uniqueIndex } from 'drizzle-orm/pg-core'
import { user } from './auth.ts'

/**
 * App tables. Rules for every synced table (see docs/PLAN.md):
 *  - id is generated by the client (UUID) so records can be created offline
 *  - workspace_id is always set. Until teams exist it equals the owner's user id.
 *  - updated_at plus soft delete via deleted_at, so sync can tell what changed
 */
const stamps = {
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  deletedAt: timestamp('deleted_at', { withTimezone: true }),
}

export const projects = pgTable(
  'projects',
  {
    id: text('id').primaryKey(),
    workspaceId: text('workspace_id').notNull(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    description: text('description').notNull().default(''),
    color: integer('color').notNull().default(1),
    ...stamps,
  },
  (t) => [index('projects_workspace_idx').on(t.workspaceId)],
)

export const tasks = pgTable(
  'tasks',
  {
    id: text('id').primaryKey(),
    workspaceId: text('workspace_id').notNull(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    projectId: text('project_id'),
    title: text('title').notNull(),
    status: text('status').notNull().default('todo'),
    priority: text('priority').notNull().default('medium'),
    /** Local calendar date, YYYY-MM-DD. */
    due: text('due'),
    recurrence: jsonb('recurrence').$type<{ freq: 'daily' | 'weekly' | 'monthly' | 'custom'; every?: number } | null>(),
    /** When the task was marked done. Cleared when it is reopened. Used for summaries and reviews. */
    completedAt: timestamp('completed_at', { withTimezone: true }),
    ...stamps,
  },
  (t) => [index('tasks_workspace_idx').on(t.workspaceId), index('tasks_user_status_idx').on(t.userId, t.status)],
)

export const timeEntries = pgTable(
  'time_entries',
  {
    id: text('id').primaryKey(),
    workspaceId: text('workspace_id').notNull(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    taskId: text('task_id'),
    projectId: text('project_id'),
    startedAt: timestamp('started_at', { withTimezone: true }).notNull(),
    /** null means the timer is running. */
    endedAt: timestamp('ended_at', { withTimezone: true }),
    ...stamps,
  },
  (t) => [
    index('time_entries_user_started_idx').on(t.userId, t.startedAt),
    // At most one running timer per user.
    uniqueIndex('time_entries_one_running_per_user')
      .on(t.userId)
      .where(sql`${t.endedAt} is null and ${t.deletedAt} is null`),
  ],
)

/** AI provider keys, encrypted by the API before they reach the database. */
export const aiProviderKeys = pgTable(
  'ai_provider_keys',
  {
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    provider: text('provider').notNull(),
    encryptedKey: text('encrypted_key').notNull(),
    ...stamps,
  },
  (t) => [uniqueIndex('ai_provider_keys_user_provider').on(t.userId, t.provider)],
)

/** Tempo conversations. Ids are generated by the client so a chat can be started before the server answers. */
export const chats = pgTable(
  'chats',
  {
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    title: text('title').notNull(),
    ...stamps,
  },
  (t) => [index('chats_user_updated_idx').on(t.userId, t.updatedAt)],
)

/** One row per message. The parts column is the AI SDK UI message (text, tool calls and results) as JSON. */
export const chatMessages = pgTable(
  'chat_messages',
  {
    id: text('id').primaryKey(),
    chatId: text('chat_id')
      .notNull()
      .references(() => chats.id, { onDelete: 'cascade' }),
    messageId: text('message_id').notNull(),
    role: text('role').notNull(),
    parts: jsonb('parts').notNull().$type<unknown[]>(),
    position: integer('position').notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [uniqueIndex('chat_messages_chat_message').on(t.chatId, t.messageId), index('chat_messages_chat_pos_idx').on(t.chatId, t.position)],
)

/** One JSON document per user: appearance and assistant preferences, so they follow you across devices. */
export const userSettings = pgTable('user_settings', {
  userId: text('user_id')
    .primaryKey()
    .references(() => user.id, { onDelete: 'cascade' }),
  data: jsonb('data').notNull().$type<Record<string, unknown>>().default({}),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
})

/** What the desktop app saw in the foreground, in small slices. Private to the person it belongs to. */
export const activitySamples = pgTable(
  'activity_samples',
  {
    /** Generated by the desktop app, so a retried upload never creates a duplicate. */
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    app: text('app').notNull(),
    title: text('title').notNull().default(''),
    startedAt: timestamp('started_at', { withTimezone: true }).notNull(),
    seconds: integer('seconds').notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index('activity_user_started_idx').on(t.userId, t.startedAt)],
)

/**
 * A person's Google Calendar connection. The tokens are encrypted by the API (AES-256-GCM) before they
 * are stored and are never sent to the browser. One row per user.
 */
export const googleConnections = pgTable('google_connections', {
  userId: text('user_id')
    .primaryKey()
    .references(() => user.id, { onDelete: 'cascade' }),
  /** The Google account that was connected, shown in Settings. */
  email: text('email'),
  /** The calendar used for events and for mirrored tasks. "primary" is the person's main calendar. */
  calendarId: text('calendar_id').notNull().default('primary'),
  encryptedRefreshToken: text('encrypted_refresh_token').notNull(),
  /** Short-lived access token kept so every request does not need a refresh. Encrypted as well. */
  encryptedAccessToken: text('encrypted_access_token'),
  accessExpiresAt: timestamp('access_expires_at', { withTimezone: true }),
  /** Mirror tasks that have a due date to Google Calendar as all-day events. */
  pushTasks: boolean('push_tasks').notNull().default(true),
  /** Reserved for incremental sync. */
  syncToken: text('sync_token'),
  lastSyncAt: timestamp('last_sync_at', { withTimezone: true }),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
})

/** Which Google event mirrors which task, so a change on either side can find the other. */
export const googleTaskLinks = pgTable(
  'google_task_links',
  {
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    taskId: text('task_id')
      .notNull()
      .references(() => tasks.id, { onDelete: 'cascade' }),
    googleEventId: text('google_event_id').notNull(),
    /** The event's etag after our own last write, so the next pull can tell our write from a change made in Google. */
    etag: text('etag'),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [uniqueIndex('google_task_links_task').on(t.taskId), uniqueIndex('google_task_links_event').on(t.userId, t.googleEventId)],
)

/** A weekly reflection: what went well and what to change. One per person per week (the Monday it starts). */
export const weeklyReviews = pgTable(
  'weekly_reviews',
  {
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    /** Monday of the week, YYYY-MM-DD. */
    weekStart: text('week_start').notNull(),
    wentWell: text('went_well').notNull().default(''),
    improve: text('improve').notNull().default(''),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.weekStart] })],
)

/**
 * One finished Focus guard session from the desktop app: how long the person stayed on work, how long a listed
 * distraction was in front, and which of their listed apps or sites it was. Never window titles.
 */
export const focusSessions = pgTable(
  'focus_sessions',
  {
    /** Generated by the desktop app, so a retried upload never creates a duplicate. */
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    startedAt: timestamp('started_at', { withTimezone: true }).notNull(),
    endedAt: timestamp('ended_at', { withTimezone: true }).notNull(),
    /** The task or project the timer was on. */
    label: text('label').notNull().default(''),
    focusedSeconds: integer('focused_seconds').notNull(),
    distractedSeconds: integer('distracted_seconds').notNull(),
    awaySeconds: integer('away_seconds').notNull().default(0),
    interruptions: integer('interruptions').notNull().default(0),
    /** [{ name, seconds }]: the listed apps or sites that took time, largest first. */
    distractions: jsonb('distractions').$type<{ name: string; seconds: number }[]>().notNull().default([]),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index('focus_user_started_idx').on(t.userId, t.startedAt)],
)
